/* PickPack 1291 — prototype only. Independent implementation inspired by Horilla's published UI patterns. No API, auth, storage, or provider calls. */
(()=>{
'use strict';
const root=document.getElementById('root');
const PAGES={dashboard:{title:'Tổng quan',desc:'Tình hình vận hành Pick Pack 1291'},people:{title:'Nhân sự',desc:'Danh sách và hồ sơ nhân sự'},shifts:{title:'Ra / vào ca',desc:'Theo dõi quét ca và user làm việc'},labor:{title:'Công nhật',desc:'Tổng hợp công theo ngày và ca'},minutes:{title:'Biên bản',desc:'Quản lý và lưu trữ biên bản'},assets:{title:'Công cụ dụng cụ',desc:'Danh mục, tình trạng và cấp phát'},pda:{title:'Mượn / trả PDA',desc:'Theo dõi thiết bị và người đang sử dụng'}};
const SIDEBAR=[{name:'BẢNG ĐIỀU KHIỂN',items:[['dashboard','grid']]},{name:'QUẢN LÝ NHÂN SỰ',items:[['people','users'],['shifts','clock'],['labor','calendar']]},{name:'HỒ SƠ & THIẾT BỊ',items:[['minutes','file'],['assets','boxes'],['pda','device']]}];
const ICONS={grid:'▦',users:'♙',clock:'◷',calendar:'▦',file:'▤',boxes:'▣',device:'▯',search:'⌕',bell:'♧',settings:'⚙',menu:'☰',close:'×',sun:'☼',moon:'☾',plus:'+',external:'↗',chev:'›',filter:'≡',check:'✓',alert:'!',right:'→'};
const people=[
 {id:'NV-001',name:'Nhân sự mẫu A',team:'Pick',shift:'Ca 1',user:'pp.demo01',state:'Đang làm việc',email:'nv001@example.invalid',initial:'MA'},
 {id:'NV-002',name:'Nhân sự mẫu B',team:'Pack',shift:'Ca 1',user:'pp.demo02',state:'Đang làm việc',email:'nv002@example.invalid',initial:'MB'},
 {id:'NV-003',name:'Nhân sự mẫu C',team:'Pack',shift:'Ca 2',user:'pp.demo03',state:'Chờ vào ca',email:'nv003@example.invalid',initial:'MC'},
 {id:'NV-004',name:'Nhân sự mẫu D',team:'Pick',shift:'Ca 2',user:'pp.demo04',state:'Chờ vào ca',email:'nv004@example.invalid',initial:'MD'},
 {id:'NV-005',name:'Nhân sự mẫu E',team:'Điều phối',shift:'Ca 1',user:'pp.demo05',state:'Đang làm việc',email:'nv005@example.invalid',initial:'ME'},
 {id:'NV-006',name:'Nhân sự mẫu F',team:'Pack',shift:'Ca 1',user:'—',state:'Nghỉ ca',email:'nv006@example.invalid',initial:'MF'}
];
const shifts=[
 {id:'CA-001',name:'Nhân sự mẫu A',staff:'NV-001',date:'14/11/2026',shift:'Ca 1',checkin:'05:31',checkout:'—',user:'pp.demo01',state:'Trong ca'},
 {id:'CA-002',name:'Nhân sự mẫu B',staff:'NV-002',date:'14/11/2026',shift:'Ca 1',checkin:'05:37',checkout:'—',user:'pp.demo02',state:'Trong ca'},
 {id:'CA-003',name:'Nhân sự mẫu E',staff:'NV-005',date:'14/11/2026',shift:'Ca 1',checkin:'05:28',checkout:'—',user:'pp.demo05',state:'Trong ca'},
 {id:'CA-004',name:'Nhân sự mẫu F',staff:'NV-006',date:'14/11/2026',shift:'Ca 1',checkin:'05:32',checkout:'14:01',user:'—',state:'Đã ra ca'},
 {id:'CA-005',name:'Nhân sự mẫu C',staff:'NV-003',date:'14/11/2026',shift:'Ca 2',checkin:'—',checkout:'—',user:'pp.demo03',state:'Chờ vào ca'}
];
const labor=[
 {id:'CN-001',name:'Nhân sự mẫu A',date:'14/11/2026',shift:'Ca 1',hours:'8,0',work:'Pick',state:'Tạm tính'},
 {id:'CN-002',name:'Nhân sự mẫu B',date:'14/11/2026',shift:'Ca 1',hours:'8,0',work:'Pack',state:'Tạm tính'},
 {id:'CN-003',name:'Nhân sự mẫu C',date:'14/11/2026',shift:'Ca 2',hours:'0,0',work:'Pack',state:'Chưa chấm'},
 {id:'CN-004',name:'Nhân sự mẫu D',date:'13/11/2026',shift:'Ca 2',hours:'8,0',work:'Pick',state:'Đã xác nhận'},
 {id:'CN-005',name:'Nhân sự mẫu E',date:'13/11/2026',shift:'Ca 1',hours:'9,0',work:'Điều phối',state:'Đã xác nhận'}
];
const minutes=[
 {id:'BB-001',name:'Ghi nhận mẫu - bàn giao ca',type:'Bàn giao',date:'14/11/2026',owner:'Nhân sự mẫu E',state:'Chờ xác nhận'},
 {id:'BB-002',name:'Ghi nhận mẫu - thiếu dụng cụ',type:'Thiết bị',date:'13/11/2026',owner:'Nhân sự mẫu B',state:'Đã lưu'},
 {id:'BB-003',name:'Ghi nhận mẫu - tác nghiệp',type:'Vận hành',date:'12/11/2026',owner:'Nhân sự mẫu A',state:'Đã lưu'}
];
const assets=[
 {id:'CCDC-01',name:'Máy quét mã vạch',type:'Thiết bị',qty:4,unit:'chiếc',holder:'Kho CCDC',state:'Sẵn sàng'},
 {id:'CCDC-02',name:'Khay phân loại',type:'Dụng cụ',qty:12,unit:'cái',holder:'Khu Pack',state:'Đang sử dụng'},
 {id:'CCDC-03',name:'Bộ sạc thiết bị',type:'Thiết bị',qty:3,unit:'bộ',holder:'Kho CCDC',state:'Sẵn sàng'},
 {id:'CCDC-04',name:'Xe đẩy hàng',type:'Dụng cụ',qty:2,unit:'xe',holder:'Khu Pick',state:'Cần kiểm tra'}
];
const pda=[
 {id:'PDA-01',name:'PDA mẫu 01',holder:'Nhân sự mẫu A',user:'pp.demo01',borrow:'05:33',return:'—',state:'Đang mượn'},
 {id:'PDA-02',name:'PDA mẫu 02',holder:'Nhân sự mẫu B',user:'pp.demo02',borrow:'05:40',return:'—',state:'Đang mượn'},
 {id:'PDA-03',name:'PDA mẫu 03',holder:'—',user:'—',borrow:'—',return:'—',state:'Sẵn sàng'}
];
const store={people,shifts,labor,minutes,assets,pda};
const columns={
 people:[['name','Nhân sự'],['id','Mã NV'],['team','Bộ phận'],['shift','Ca'],['user','User làm việc'],['state','Trạng thái']],
 shifts:[['name','Nhân sự'],['date','Ngày'],['shift','Ca'],['checkin','Vào ca'],['checkout','Ra ca'],['user','User làm việc'],['state','Trạng thái']],
 labor:[['name','Nhân sự'],['date','Ngày'],['shift','Ca'],['work','Công việc'],['hours','Giờ công'],['state','Trạng thái']],
 minutes:[['name','Tên biên bản'],['id','Mã'],['type','Loại'],['date','Ngày'],['owner','Người lập'],['state','Trạng thái']],
 assets:[['name','Tên CCDC'],['id','Mã'],['type','Loại'],['qty','Số lượng'],['holder','Vị trí'],['state','Trạng thái']],
 pda:[['name','Thiết bị'],['holder','Người mượn'],['user','User làm việc'],['borrow','Giờ mượn'],['return','Giờ trả'],['state','Trạng thái']]
};
const state={view:'dashboard',theme:'light',search:'',filter:'all',layout:'table',drawer:'',modal:'',sidebar:false,notice:''};
const escape=s=>String(s??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const qs=new URLSearchParams(location.search);state.view=PAGES[qs.get('view')]?qs.get('view'):'dashboard';state.theme=qs.get('theme')==='dark'?'dark':'light';state.drawer=qs.get('record')||'';
const href=(view=state.view,record='',theme=state.theme)=>`app.html?view=${encodeURIComponent(view)}&theme=${theme}`+(record?`&record=${encodeURIComponent(record)}`:'');
const badge=(v)=>{const s=String(v);const type=/Chờ|Cần kiểm tra|Chưa/.test(s)?'warn':/Đã lưu|Đã xác nhận|Sẵn sàng|Đã ra/.test(s)?'neutral':/Trong ca|Đang|Tạm tính/.test(s)?'good':'neutral';return `<span class="status ${type}"><span class="status-dot"></span>${escape(s)}</span>`};
const avatar=(x,big=false)=>`<span class="person-avatar ${big?'big':''}" aria-hidden="true">${escape(x.initial || String(x.name||'A').slice(-2).toUpperCase())}</span>`;
function side(){return `<aside class="sidebar ${state.sidebar?'is-open':''}" aria-label="Điều hướng PickPack"><div class="side-top"><div class="brand-icon">P<span>+</span></div><div><strong>PickPack 1291</strong><small>QUẢN LÝ VẬN HÀNH</small></div><button class="mobile-hide" data-action="close-nav" aria-label="Đóng menu">×</button></div><div class="sidebar-scroll"><div class="location-chip"><span class="location-icon">⌂</span><div><strong>Kho 1291</strong><small>Bản mẫu giao diện</small></div><span class="caret">⌄</span></div>${SIDEBAR.map(group=>`<div class="side-group"><span class="group-title">${group.name}</span>${group.items.map(([view,icon])=>`<div class="side-link ${state.view===view?'selected':''}"><a class="nav-main" href="${href(view)}" data-nav="${view}" aria-current="${state.view===view?'page':'false'}"><span class="nav-icon">${ICONS[icon]}</span><span>${PAGES[view].title}</span></a><a class="nav-external" href="${href(view)}" target="_blank" rel="noopener noreferrer" title="Mở ${PAGES[view].title} trong tab mới" aria-label="Mở tab mới: ${PAGES[view].title}">↗</a></div>`).join('')}</div>`).join('')}</div><div class="side-bottom"><span class="online-dot"></span><div><strong>Admin Demo</strong><small>Không kết nối hệ thống thật</small></div><a href="index.html" title="Thoát bản mẫu" aria-label="Về màn hình giới thiệu">⇥</a></div></aside>`}
function top(){return `<header class="topbar"><div class="top-left"><button class="icon-button menu-button" data-action="toggle-nav" aria-label="Mở menu">☰</button><div class="breadcrumb">Hệ thống <span>›</span><strong>${PAGES[state.view].title}</strong></div></div><div class="top-right"><div class="top-search"><span>⌕</span><input id="global-search" type="search" placeholder="Tìm nhanh trong ${PAGES[state.view].title.toLowerCase()}..." value="${escape(state.search)}" aria-label="Tìm nhanh"></div><span class="top-divider"></span><button class="icon-button" data-action="theme" title="Chuyển sáng/tối" aria-label="Chuyển chế độ màu">${state.theme==='light'?'☾':'☼'}</button><button class="icon-button notif" data-action="notifications" title="Thông báo mẫu" aria-label="Thông báo mẫu">♧<i></i></button><div class="top-profile">${avatar({initial:'AD'})}<div><strong>Admin Demo</strong><small>Chỉ review giao diện</small></div><span class="caret">⌄</span></div></div></header>`}
function pageHead(action='',other=''){return `<div class="page-header"><div><div class="eyebrow">PICK PACK 1291 / <span>${PAGES[state.view].title.toUpperCase()}</span></div><h1>${PAGES[state.view].title}</h1><p>${PAGES[state.view].desc}. <b>Toàn bộ dữ liệu hiển thị là giả lập.</b></p></div><div class="header-actions">${other}<a href="${href()}" target="_blank" rel="noopener noreferrer" class="btn ghost" title="Mở trang này trong tab mới">↗ Tab mới</a>${action}</div></div>`}
function stat(label,value,small,accent='blue',icon='▦'){return `<div class="metric-card"><div class="metric-top"><span>${label}</span><span class="metric-icon ${accent}">${icon}</span></div><div class="metric-number">${value}</div><div class="metric-foot">${small}</div></div>`}
function activity(){return `<section class="panel activity-panel"><div class="panel-title"><div><h2>Hoạt động gần đây</h2><p>Dòng thời gian thao tác giả lập</p></div><span class="muted">Hôm nay</span></div><div class="timeline">${[['09:12','Cấp phát PDA mẫu 02','Thiết bị · Nhân sự mẫu B'],['08:36','Tạo biên bản bàn giao ca','Hồ sơ · Đang chờ xác nhận'],['06:12','Cập nhật user làm việc','Nhân sự · pp.demo01'],['05:31','Ghi nhận nhân sự vào ca','Ra / vào ca · Ca 1']].map(([time,name,sub],i)=>`<div class="timeline-row"><span class="timeline-indicator ${i===0?'current':''}"></span><div><strong>${name}</strong><small>${sub}</small></div><time>${time}</time></div>`).join('')}</div></section>`}
function workload(){const points=[38,55,43,73,62,86,68],labs=['05h','07h','09h','11h','13h','15h','17h'];return `<section class="panel chart-panel"><div class="panel-title"><div><h2>Minh họa phân bổ nhân sự</h2><p>Ví dụ hiển thị theo khung giờ, không phải dữ liệu thực</p></div><span class="legend"><i></i>Đang làm việc</span></div><div class="chart-area"><div class="chart-lines"><span>100%</span><span>75%</span><span>50%</span><span>25%</span></div><div class="chart-bars">${points.map((x,i)=>`<div class="chart-col"><div class="bar-wrap"><div class="bar" style="height:${x}%"><span>${x}%</span></div></div><small>${labs[i]}</small></div>`).join('')}</div></div></section>`}
function attention(){return `<section class="panel alert-panel"><div class="panel-title"><div><h2>Cần kiểm tra</h2><p>Các mục minh họa cần thao tác</p></div><span class="bubble">03</span></div><div class="alert-list"><a href="${href('minutes')}" class="alert-row"><span class="alert-icon amber">!</span><span><strong>Biên bản chờ xác nhận</strong><small>1 bản ghi mẫu</small></span><span>›</span></a><a href="${href('assets')}" class="alert-row"><span class="alert-icon amber">!</span><span><strong>CCDC cần kiểm tra</strong><small>1 thiết bị minh họa</small></span><span>›</span></a><a href="${href('shifts')}" class="alert-row"><span class="alert-icon blue">◷</span><span><strong>Nhân sự chờ vào ca</strong><small>1 bản ghi mẫu</small></span><span>›</span></a></div></section>`}
function dashboard(){return `<div class="page-content">${pageHead(`<button class="btn primary" data-action="add">+ Tạo ghi nhận mẫu</button>`)}<div class="demo-note"><span class="note-icon">i</span><span><strong>CHẾ ĐỘ XEM TRƯỚC:</strong> đây là giao diện được xây dựng theo mô hình Horilla; số liệu, người và thiết bị bên dưới hoàn toàn giả lập, không có đăng nhập thật hay kết nối API.</span></div><div class="metrics">${stat('Nhân sự mẫu','06','3 đang làm việc · 2 chờ vào ca','blue','♙')}${stat('Đang trong ca','03','Dữ liệu mẫu ngày 14/11','green','◷')}${stat('PDA đang mượn','02 / 03','Còn 1 thiết bị sẵn sàng','purple','▯')}${stat('Biên bản chờ duyệt','01','Danh sách minh họa','orange','▤')}</div><div class="two-col">${workload()}${attention()}</div><div class="two-col lower">${activity()}<section class="panel shortcut-panel"><div class="panel-title"><div><h2>Truy cập nhanh</h2><p>Những chức năng dùng thường xuyên</p></div></div><div class="shortcut-grid">${[['people','♙','Tra cứu nhân sự'],['shifts','◷','Ghi nhận ra/vào'],['labor','▦','Bảng công nhật'],['minutes','▤','Biên bản'],['assets','▣','Kho CCDC'],['pda','▯','Mượn / trả PDA']].map(([view,ic,title])=>`<a href="${href(view)}" class="shortcut"><span>${ic}</span><strong>${title}</strong><small>→</small></a>`).join('')}</div></section></div></div>`}
function tableCell(row,key,view){if(key==='name')return `<div class="cell-name">${view==='people'?avatar(row):''}<div><strong>${escape(row.name)}</strong>${view==='people'?`<small>${escape(row.email)}</small>`:''}</div></div>`;if(key==='state')return badge(row[key]);if(key==='id')return `<span class="mono">${escape(row[key])}</span>`;return escape(row[key])}
function filtered(){const set=store[state.view]||[];let rows=set.filter(x=>Object.values(x).some(v=>String(v).toLowerCase().includes(state.search.toLowerCase())));if(state.filter!=='all')rows=rows.filter(x=>String(x.state)===state.filter);return rows}
function controls(){let statuses=[...new Set((store[state.view]||[]).map(x=>x.state))];return `<div class="table-controls"><div class="table-control-left"><span class="listing-icon">≡</span><span class="records-label">Danh sách <b>${(store[state.view]||[]).length}</b></span><span class="separator"></span><label class="filter-label">Trạng thái <select id="status-filter" aria-label="Lọc theo trạng thái"><option value="all">Tất cả</option>${statuses.map(x=>`<option value="${escape(x)}" ${state.filter===x?'selected':''}>${escape(x)}</option>`).join('')}</select></label></div><div class="table-control-right"><button class="btn icon-label ${state.layout==='table'?'active':''}" data-action="layout-table" aria-label="Dạng bảng">☷ <span>Bảng</span></button><button class="btn icon-label ${state.layout==='cards'?'active':''}" data-action="layout-cards" aria-label="Dạng thẻ">▦ <span>Thẻ</span></button></div></div>`}
function table(){const cols=columns[state.view],rows=filtered();return `<section class="panel table-panel">${controls()}${rows.length?state.layout==='cards'?`<div class="record-cards">${rows.map(r=>`<div class="record-card"><div><strong>${escape(r.name)}</strong>${badge(r.state)}</div><dl>${cols.slice(1,-1).map(([k,label])=>`<div><dt>${label}</dt><dd>${escape(r[k])}</dd></div>`).join('')}</dl><a href="${href(state.view,r.id)}" target="_blank" rel="noopener noreferrer">Chi tiết ↗</a></div>`).join('')}</div>`:`<div class="table-scroll"><table><thead><tr><th><input type="checkbox" aria-label="Chọn tất cả" disabled></th>${cols.map(([,lab])=>`<th>${lab}</th>`).join('')}<th>Thao tác</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td><input type="checkbox" aria-label="Chọn ${escape(r.id)}" disabled></td>${cols.map(([k])=>`<td>${tableCell(r,k,state.view)}</td>`).join('')}<td><a class="row-open" href="${href(state.view,r.id)}" target="_blank" rel="noopener noreferrer" title="Mở chi tiết tab mới">↗</a><button class="row-open" data-record="${escape(r.id)}" aria-label="Xem chi tiết ${escape(r.id)}">›</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><strong>Không tìm thấy bản ghi phù hợp</strong><span>Thử điều chỉnh bộ lọc hoặc từ khóa</span></div>`}<div class="table-footer"><span>Hiển thị ${rows.length} / ${(store[state.view]||[]).length} bản ghi mẫu</span><span>Trang 1 / 1</span></div></section>`}
function modulePage(){let n=(store[state.view]||[]).length;let call=state.view==='shifts'?'Ghi nhận quét mẫu':state.view==='pda'?'Mượn / trả mẫu':state.view==='people'?'Thêm nhân sự mẫu':state.view==='minutes'?'Tạo biên bản mẫu':state.view==='assets'?'Thêm CCDC mẫu':'Thêm công nhật mẫu';return `<div class="page-content">${pageHead(`<button class="btn primary" data-action="add">+ ${call}</button>`)}<div class="module-summary">${stat('Tổng bản ghi',String(n).padStart(2,'0'),'Giả lập trong trình duyệt','blue','≡')}${stat('Đang xử lý',String((store[state.view]||[]).filter(r=>/Chờ|Đang|Trong ca|Tạm tính/.test(r.state)).length).padStart(2,'0'),'Trạng thái minh họa','orange','◷')}${stat('Mục được xem','01','Tab hiện tại','green','▦')}</div>${table()}</div>`}
function drawer(){if(!state.drawer)return '';const row=(store[state.view]||[]).find(x=>x.id===state.drawer);if(!row)return '';return `<div class="drawer-shade" data-action="close-drawer"></div><aside class="detail-drawer" role="dialog" aria-modal="true" aria-label="Chi tiết ${escape(row.id)}"><div class="detail-head"><div><small>CHI TIẾT BẢN GHI MẪU</small><h2>${escape(row.name)}</h2></div><button class="icon-button" data-action="close-drawer" aria-label="Đóng chi tiết">×</button></div><div class="detail-content"><div class="detail-hero"><span class="detail-icon">${state.view==='people'?'♙':state.view==='pda'?'▯':'▤'}</span><div><strong>${escape(row.name)}</strong><small>${escape(row.id)}</small></div></div>${badge(row.state)}<div class="detail-fields">${(columns[state.view]||[]).slice(1).map(([k,label])=>`<div><span>${label}</span><b>${escape(row[k])}</b></div>`).join('')}</div><div class="detail-tip">Thông tin chỉ phục vụ duyệt giao diện; không có dữ liệu lưu trên server.</div><a class="btn primary wide center" href="${href(state.view,row.id)}" target="_blank" rel="noopener noreferrer">Mở chi tiết trong tab mới ↗</a></div></aside>`}
function modal(){if(!state.modal)return '';const title=state.view==='dashboard'?'Ghi nhận nhanh':`Thêm bản ghi ${PAGES[state.view].title.toLowerCase()}`;return `<div class="modal-overlay" data-action="close-modal"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><div><span>CHỈ MINH HỌA</span><h2 id="modal-title">${title}</h2></div><button class="icon-button" data-action="close-modal" aria-label="Đóng cửa sổ">×</button></div><form id="create-form"><p>Tạo bản ghi mẫu ngay trên trình duyệt. Dữ liệu sẽ mất khi tải lại trang.</p><label>Tên bản ghi mẫu <input name="demoName" maxlength="80" minlength="2" required placeholder="Nhập tên minh họa" autocomplete="off"></label><label>Ghi chú <textarea name="note" rows="3" maxlength="160" placeholder="Không nhập thông tin thật"></textarea></label><div class="modal-actions"><button type="button" class="btn ghost" data-action="close-modal">Hủy</button><button class="btn primary" type="submit">Tạo bản ghi mẫu</button></div></form></section></div>`}
function toast(){return state.notice?`<div class="toast" role="status">${escape(state.notice)}<button data-action="clear-notice" aria-label="Đóng thông báo">×</button></div>`:''}
function render(){document.documentElement.setAttribute('data-theme',state.theme);if(document.body.dataset.screen==='login'){renderLogin();return}root.innerHTML=`${side()}<div class="screen-shade ${state.sidebar?'show':''}" data-action="close-nav"></div><div class="app-main">${top()}${state.view==='dashboard'?dashboard():modulePage()}<footer class="site-footer">PickPack 1291 · UI prototype v0.4 · Dữ liệu giả · Không kết nối hệ thống thực</footer></div>${drawer()}${modal()}${toast()}`}
function renderLogin(){root.innerHTML=`<main class="login-screen"><div class="login-panel"><div class="login-left"><div class="login-brand"><span class="brand-icon">P<span>+</span></span><span>PickPack 1291</span></div><div class="login-art"><div class="art-greeting">QUẢN LÝ VẬN HÀNH</div><h1>Một nơi cho mọi hoạt động Pick & Pack.</h1><p>Giao diện tham khảo mô hình quản trị nhân sự Horilla, được thiết kế lại cho nghiệp vụ kho 1291.</p><div class="art-metrics"><div><strong>07</strong><span>Phân hệ</span></div><div><strong>03</strong><span>PDA tối đa*</span></div><div><strong>05</strong><span>Web tối đa*</span></div></div></div><small>* Mục tiêu thiết kế; chưa có hệ thống thực.</small></div><div class="login-right"><span class="login-kicker">BẢN MẪU GIAO DIỆN</span><h2>Chào mừng trở lại</h2><p>Chọn tài khoản giả lập bên dưới để trải nghiệm màn hình quản lý.</p><div class="login-person"><span class="person-avatar big">AD</span><div><strong>Admin Demo</strong><small>Không liên quan tài khoản Firebase hoặc Inventory</small></div><span class="demo-tick">✓</span></div><a class="btn primary login-submit" href="${href('dashboard')}">Vào hệ thống mẫu <span>→</span></a><div class="login-caution">Đây không phải cơ chế đăng nhập hoặc phân quyền. Không nhập dữ liệu nhân sự thật vào bản mẫu này.</div><div class="login-links"><a href="${href('people')}" target="_blank" rel="noopener noreferrer">Xem ngay danh sách nhân sự ↗</a><button data-action="theme" class="text-button">${state.theme==='dark'?'☼ Sáng':'☾ Tối'}</button></div></div></div></main>`}
function safeHistory(method,url){try{history[method](null,'',url)}catch{ /* Browser file:// history restrictions do not block UI. */ }}
function closeStuff(){state.sidebar=false;state.modal='';state.drawer=''}
function setView(view){state.view=view;state.search='';state.filter='all';state.drawer='';state.sidebar=false;safeHistory('pushState',href(view));render();window.scrollTo(0,0)}
function addRecord(name){if(state.view==='dashboard')state.view='minutes';const key=state.view;const id=`DEMO-${String((store[key]||[]).length+1).padStart(3,'0')}`;const obj={id,name,state:'Chờ xác nhận'};for(const [k] of columns[key])if(!(k in obj))obj[k]=k==='date'?'14/11/2026':k==='qty'?'1':'—';store[key].unshift(obj);state.search='';state.filter='all';state.notice=`Đã thêm ${id} trong tab này (chỉ giả lập)`;state.modal='';render()}
root.addEventListener('submit',e=>{if(e.target.id==='create-form'){e.preventDefault();const fd=new FormData(e.target);const name=String(fd.get('demoName')||'').trim();if(name.length<2)return;addRecord(name)}});
root.addEventListener('click',e=>{
 const nav=e.target.closest('[data-nav]');if(nav){if(e.button===0&&!e.ctrlKey&&!e.metaKey&&!e.shiftKey&&!e.altKey){e.preventDefault();setView(nav.dataset.nav)}return}
 const a=e.target.closest('[data-action]');if(!a)return;const act=a.dataset.action;
 if(act==='close-modal' && a.classList.contains('modal-overlay') && e.target.closest('.modal'))return;
 if(['toggle-nav','close-nav','theme','add','close-modal','close-drawer','notifications','layout-table','layout-cards','clear-notice'].includes(act))e.preventDefault();
 switch(act){case'toggle-nav':state.sidebar=!state.sidebar;break;case'close-nav':state.sidebar=false;break;case'theme':state.theme=state.theme==='light'?'dark':'light';safeHistory('replaceState',document.body.dataset.screen==='app'?href(state.view,state.drawer):'index.html?theme='+state.theme);break;case'add':state.modal='new';break;case'close-modal':state.modal='';break;case'close-drawer':state.drawer='';safeHistory('replaceState',href());break;case'notifications':state.notice='Thông báo mẫu: không kết nối dữ liệu thực';break;case'layout-table':state.layout='table';break;case'layout-cards':state.layout='cards';break;case'clear-notice':state.notice='';break;}
 render();
 });
root.addEventListener('click',e=>{const btn=e.target.closest('[data-record]');if(btn){state.drawer=btn.dataset.record;safeHistory('replaceState',href(state.view,state.drawer));render()}});
root.addEventListener('input',e=>{if(e.target.id==='global-search'){const input=e.target;state.search=input.value;const pos=input.selectionStart;render();const newInput=root.querySelector('#global-search');if(newInput){newInput.focus();newInput.setSelectionRange(pos,pos)}}});
root.addEventListener('change',e=>{if(e.target.id==='status-filter'){state.filter=e.target.value;render()}});
window.addEventListener('popstate',()=>{const p=new URLSearchParams(location.search);state.view=PAGES[p.get('view')]?p.get('view'):'dashboard';state.theme=p.get('theme')==='dark'?'dark':'light';state.drawer=p.get('record')||'';state.search='';state.filter='all';render()});
window.addEventListener('keydown',e=>{if(e.key==='Escape'){closeStuff();render()}});
render();
})();
